(window.TNQ=window.TNQ||[]).push({"terms":{"요수량":{"d":"작물이 건물 한 단위를 만드는 데 소모하는 물의 양으로, 클수록 물을 많이 필요로 한다.","r":[]},"광포화점":{"d":"광합성 속도가 더는 늘지 않고 일정해지기 시작하는 빛의 세기.","r":["광보상점"]},"광보상점":{"d":"광합성량과 호흡량이 같아져 겉보기 광합성이 없어지는 빛의 세기.","r":["광포화점"]},"감광성":{"d":"일장의 길고 짧음에 반응하여 출수와 개화가 빨라지거나 늦어지는 성질.","r":["감온성","기본영양생장성"]},"감온성":{"d":"온도의 고저에 반응하여 출수와 개화가 빨라지거나 늦어지는 성질.","r":["감광성","기본영양생장성"]},"기본영양생장성":{"d":"출수에 알맞은 일장과 온도에서도 일정한 영양생장이 필요한 성질.","r":["감광성","감온성"]},"수발아":{"d":"수확 전 이삭에 달린 종자가 비를 맞아 싹이 트는 현상.","r":[]},"예냉":{"d":"수확한 농산물의 품온을 수송이나 저장 전에 빨리 낮추는 처리.","r":["큐어링"]},"큐어링":{"d":"수확 시 생긴 상처를 아물게 하는 처리로, 고온 다습 조건에 두어 코르크층을 만든다.","r":["예냉"]},"맹아":{"d":"휴면이 끝난 뒤 구근이나 덩이줄기에서 돋아나는 싹.","r":[]},"호흡비급등형":{"d":"수확 후 숙성 중 호흡이 일시적으로 급증하고 에틸렌이 많이 생성되는 과실.","r":[]},"포화용존산소량":{"d":"일정한 온도에서 물에 최대한 녹을 수 있는 산소의 양.","r":[]}},"notes":{"PE 필름, PVC 필름, EVA 필름은 모두 연질필름이다":"연질필름은 가소제를 넣어 부드럽게 만든 피복재이며 세 가지 모두 이에 해당합니다.","leaf/fruit ratio":"엽과비는 과실 하나당 잎의 수를 나타내는 비율로, 영어 표현은 잎 대 과실의 비를 뜻합니다.","강풍은 매개곤충의 활동을 저하시켜 수분과 수정을 방해한다":"곤충 활동이 약해지면 꽃가루가 암술에 닿지 못해 수분이 안 되고 결국 수정도 방해받습니다.","개화기의 냉온으로 불임현상이 나타나는 냉해":"장해형냉해는 꽃 필 무렵의 저온 때문에 꽃가루가 제 기능을 못 해 열매를 못 맺는 냉해예요.","결실기에 종실이 이삭에 달린 채로 싹이 트는 것을 말한다":"수확 전 낟알이 이삭에 붙은 채 발아하는 현상으로, 품질과 수량이 떨어지는 원인이 되죠.","결실기의 벼가 우기에 도복이 되었을 때 자주 발생한다":"비가 잦은 시기에 벼가 쓰러져 이삭이 젖은 채 오래 있으면 낟알이 싹을 틔우기 쉽습니다.","고온기 수확 시 품온이 높아 바로 수송할 경우 부패하기 쉬우므로 예냉을 실시 한다":"더운 때 수확한 수박은 품온이 높아 부패하기 쉬우므로 수송 전에 예냉으로 온도를 낮추죠.","광보상점은 글록시니아보다 초롱꽃이 더 낮다":"광보상점이 낮을수록 약한 빛에서도 광합성이 호흡을 앞지르므로 초롱꽃이 그늘에 더 잘 견딥니다.","광포화점은 상추보다 토마토가 더 높다":"토마토는 상추보다 센 빛에서도 광합성이 계속 늘어나는 양지식물에 가까운 작물이죠.","기본영양생장성과 감광성이 작고 감온성이 커서":"이 유형은 일장 반응이 약하고 온도에 민감해 기온이 높을수록 출수가 빨라지는 성질입니다.","기본영양생장성과 감온성이 작고 감광성이 커서":"이 유형은 온도 반응이 약하고 낮이 짧아지는 일장 변화에 민감하게 반응하는 성질이에요.","기본영양생장성이 크고 감광성과 감온성이 작아서":"이 유형은 일장과 온도 반응이 약하고 일정한 영양생장을 거쳐야 이삭이 패는 성질이 강합니다.","기본영양생장에 지배되는 통일형 품종 벼가 여기에 해당한다":"통일형 벼는 환경보다 자체의 기본영양생장 기간에 따라 출수 시기가 정해지는 품종이에요.","높아질수록 포화용존산소량은 적어진다":"물의 온도가 오르면 녹을 수 있는 산소의 최대량이 줄어 뿌리가 쓸 산소가 부족해지기 쉽습니다.","높을수록 과실의 크기가 커진다":"과실 하나에 잎이 많이 달릴수록 광합성 산물이 더 많이 공급되어 열매가 굵어집니다.","당이 축적되지 않아 과실과 채소는 단맛이 없어지고 생육이 억제된다":"고온에서는 호흡으로 당이 소모되어 열매에 쌓이지 못하므로 맛이 밍밍하고 자람도 더뎌집니다.","만생종보다 수발아가 잘 발생한다":"조생종은 수확기가 일러 아직 덥고 비가 많은 시기와 겹치기 쉬워 수발아 위험이 큰 편이에요.","목초와 호냉성 채소의 하우스 재배시에 주로 발생한다":"서늘한 기후를 좋아하는 작물은 여름 고온에 약해 하우스 안에서 생육이 쇠퇴하는 하고현상이 생기죠.","물질이 분해될 때 암모니아에 의해 장해를 받을 수 있다":"고온에서 단백질 등이 분해되며 생긴 암모니아가 쌓이면 세포에 해를 줄 수 있어요.","뿌림 골을 만들고 그곳에 줄지어 종자를 뿌리는 방법이다":"골을 파서 그 안에 씨앗을 줄 맞춰 뿌리는 조파로, 관리와 제초 작업이 쉬워집니다.","상처를 유발하여 호흡량을 증가시킨다":"바람에 잎이 서로 부딪혀 상처가 나면 아문 자리를 만들기 위해 호흡이 늘어 양분이 소모됩니다.","상처를 통한 병해충의 발생을 촉진한다":"상처 부위는 병원균과 해충이 침입하는 통로가 되어 병해충 발생이 늘어납니다.","생육기간이 주로 감광성에 지배되며 만생종 벼가 여기에 해당한다":"만생종 벼는 가을 단일 조건이 되어야 이삭이 패므로 생육기간이 감광성에 좌우됩니다.","생육기간이 주로 감온성에 지배되며 조생종 벼가 여기에 해당한다":"조생종 벼는 온도가 오르면 일찍 이삭이 패므로 생육기간이 감온성에 따라 달라집니다.","생육 초기부터 냉온에 처하여 등숙불량이 초래되는 냉해":"지연형냉해는 초기부터 낮은 온도가 이어져 생육이 늦어지고 낟알이 여물지 못하는 냉해입니다.","세포막 지방의 유동성이 커진다":"온도가 높아지면 세포막을 이루는 지방이 묽어져 막이 헐거워지고 물질 출입이 불안정해집니다.","수매전염성 병원균의 유입 억제를 위해 급액 전에 살균한다":"물을 타고 번지는 병원균이 양액 순환계로 들어가지 못하도록 공급 전에 미리 소독해요.","수확 시 생긴 상처를 빨리 아물게 하기 위해 큐어링을 실시한다":"감자는 상처 부위로 썩음균이 들어가기 쉬워 큐어링으로 껍질에 보호층을 만들어 줍니다.","신장을 억제하고 엽육을 두껍게 한다":"자외선을 받으면 줄기가 길게 자라지 못하고 잎살이 두꺼워져 작물체가 작고 단단해집니다.","안토시아닌계 색소의 발현을 촉진한다":"자외선은 붉거나 보라색을 내는 안토시아닌 색소가 잘 만들어지게 해 과실의 착색을 돕습니다.","양액내 무기양분들은 수용성 상태로 유지하는 것이 필요하다":"뿌리는 물에 녹은 이온 상태의 양분만 흡수하므로 침전되지 않게 용해된 상태로 둬야 합니다.","요수량이 낮은 품종을 재배한다":"요수량이 낮으면 적은 물로 생산할 수 있으므로 가뭄에 강하고 물이 부족한 환경에 알맞습니다.","유기물의 과잉 소모와 질소 대사의 이상현상이 나타난다":"고온에서는 호흡이 지나쳐 저장 양분이 빨리 소모되고 단백질 합성에 필요한 질소 대사가 흐트러집니다.","이랑을 세우고 이랑에 파종하는 방식이다":"휴립휴파법은 두둑을 높이 쌓아 그 위에 씨앗을 뿌리는 방식으로, 배수와 통기가 좋아집니다.","작물의 열을 빼앗아 작물체온을 저하시킨다":"센 바람은 잎 표면의 열을 빼앗아 증산을 촉진하고 체온을 떨어뜨려 생육을 늦춥니다.","조생종보다 수발아가 덜 발생한다":"만생종은 늦게 여물어 수확기가 건조하고 서늘한 때와 맞물리므로 수발아가 상대적으로 적습니다.","질소과용이 발생하지 않도록 한다":"질소를 지나치게 주면 줄기와 잎만 웃자라 쓰러지고 병에 약해지니 알맞은 양만 줍니다.","카르티노이드계의 색소 생성을 촉진한다":"청색광은 카로티노이드 계열의 색소를 만들게 하여 열매나 잎의 노랑과 주황 발색을 돕습니다.","칼륨결핍이 발생하지 않도록 재배한다":"칼륨이 모자라면 잎 가장자리가 말라 가는 증상이 생기므로 칼륨 비료로 이를 막아야 해요.","타가수분을 위해 20 % 내외로 혼식한다":"자가불화합성 과수는 다른 품종의 꽃가루가 필요하므로 수분수를 전체의 20 % 안팎으로 섞어 심어요.","호박은 기장에 비해 요수량이 높다":"요수량이 높다는 것은 건물 하나를 만드는 데 물이 더 든다는 뜻이라, 호박이 기장보다 물을 많이 쓰는 작물이에요.","화분매개곤충의 활동을 억제한다":"바람이 세면 벌 등 꽃가루를 옮기는 곤충이 날지 못하므로 수분 기회가 줄어요.","휴면이 끝나면 싹이 자라 상품성이 저하될 수 있으므로 맹아 억제 처리를 한다":"마늘은 휴면이 끝나면 싹이 나와 품질이 떨어지므로 저장 중 싹이 트지 않도록 억제하죠."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
